package com.schedulingsystem.api.controller;
import com.schedulingsystem.api.dto.*; import com.schedulingsystem.api.service.*; import jakarta.validation.Valid; import org.springframework.http.HttpStatus; import org.springframework.web.bind.annotation.*; import java.time.LocalDate; import java.util.List;
@RestController @RequestMapping("/api/public") public class PublicAppointmentController { private final AppointmentService appointments; private final ServiceService services; public PublicAppointmentController(AppointmentService appointments,ServiceService services){this.appointments=appointments;this.services=services;} @GetMapping("/services") public List<ServiceResponse> services(){return services.findActive();} @GetMapping("/availability") public AvailabilityResponse availability(@RequestParam LocalDate date,@RequestParam Long serviceId){return appointments.availability(date,serviceId);} @PostMapping("/appointments") @ResponseStatus(HttpStatus.CREATED) public AppointmentResponse create(@Valid @RequestBody CreateAppointmentRequest request){return appointments.create(request);} }
